using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
namespace PZ3D {
 sealed class DeploymentRecord {public string Root;public Dictionary<string,string> Files=new Dictionary<string,string>();public string RuntimeMarker;}
 static class PortableDeployment {
  const string Manifest="orange-installation.json",Marker=".orange-installed-runtime";
  static JavaScriptSerializer Json=new JavaScriptSerializer();
  public static string ValidateRoot(string root){string full=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);LauncherMaintenance.NoReparse(full);string drive=Path.GetPathRoot(full).TrimEnd(Path.DirectorySeparatorChar);if(full==drive||full.Length<drive.Length+3||!string.IsNullOrEmpty(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile))&&full.Equals(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),StringComparison.OrdinalIgnoreCase)||full.Equals(Environment.GetFolderPath(Environment.SpecialFolder.Windows),StringComparison.OrdinalIgnoreCase)||File.Exists(Path.Combine(full,"ProjectZomboid64.exe")))throw new Exception("请选择独立的工具文件夹，不能安装到盘符根目录、用户根目录、Windows 或游戏目录。");return full;}
  static string Target(string root,string name){if(string.IsNullOrWhiteSpace(name)||Path.GetFileName(name)!=name||name.IndexOfAny(new[]{'/', '\\', ':'})>=0||name=="."||name=="..")throw new Exception("安装清单文件名越界。");string path=Path.Combine(root,name);LauncherMaintenance.NoReparse(path);return path;}
  public static object Install(string root,Dictionary<string,byte[]> files){root=ValidateRoot(root);if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("目标文件夹不为空。请选择新的独立目录；不会覆盖已有程序或个人文件。");if(files.Count==0||!files.ContainsKey("橙子启动器.exe")||!files.ContainsKey("卸载橙子启动器.exe"))throw new Exception("安装资源不完整。");foreach(var f in files){Target(root,f.Key);if(f.Value==null||f.Value.Length==0)throw new Exception("安装资源为空。");}Directory.CreateDirectory(root);var record=new DeploymentRecord{Root=root,RuntimeMarker=Guid.NewGuid().ToString("N")};var written=new List<string>();try{foreach(var file in files){string path=Target(root,file.Key);File.WriteAllBytes(path,file.Value);written.Add(path);record.Files[file.Key]=DlssInstaller.Hash(file.Value);}string runtime=Path.Combine(root,"OrangeLauncherRuntime");LauncherMaintenance.NoReparse(runtime);Directory.CreateDirectory(runtime);File.WriteAllText(Path.Combine(runtime,Marker),record.RuntimeMarker);File.WriteAllText(Path.Combine(root,Manifest),Json.Serialize(record),new UTF8Encoding(false));return new{message="已安装到 "+root+"。直接打开橙子启动器.exe；卸载请运行卸载橙子启动器.exe。未写注册表。"};}catch{foreach(string path in written)if(File.Exists(path)&&record.Files.ContainsKey(Path.GetFileName(path))&&DlssInstaller.HashFile(path)==record.Files[Path.GetFileName(path)])File.Delete(path);throw;}}
  static DeploymentRecord Read(string root){root=ValidateRoot(root);string file=Target(root,Manifest);if(!File.Exists(file)||new FileInfo(file).Length>65536)throw new Exception("找不到有效安装清单，拒绝删除任意目录。");var record=Json.Deserialize<DeploymentRecord>(File.ReadAllText(file));if(record==null||record.Root!=root||record.Files==null||record.Files.Count>16||string.IsNullOrWhiteSpace(record.RuntimeMarker))throw new Exception("安装记录与当前目录不一致。");foreach(var entry in record.Files)Target(root,entry.Key);return record;}
  public static string Uninstall(string root,string runningExe=null){root=ValidateRoot(root);string recordPath=Target(root,Manifest);if(File.Exists(recordPath)&&new FileInfo(recordPath).Length<=CoreReleaseProtocol.MaxManifestBytes){var fields=Json.DeserializeObject(File.ReadAllText(recordPath)) as Dictionary<string,object>;if(fields!=null&&fields.ContainsKey("schema")){if(Convert.ToInt32(fields["schema"])!=2)throw new InvalidDataException("Unknown installation schema.");return CoreDeployment.Uninstall(root,runningExe);}}var record=Read(root);var kept=new List<string>();foreach(var entry in record.Files){string file=Target(root,entry.Key);if(!File.Exists(file))continue;if(DlssInstaller.HashFile(file)!=entry.Value){kept.Add(entry.Key+"（已修改）");continue;}if(runningExe!=null&&Path.GetFullPath(file).Equals(Path.GetFullPath(runningExe),StringComparison.OrdinalIgnoreCase))continue;try{File.Delete(file);}catch{kept.Add(entry.Key+"（文件占用）");}}
   string runtime=Path.Combine(root,"OrangeLauncherRuntime"),marker=Path.Combine(runtime,Marker);LauncherMaintenance.NoReparse(runtime);LauncherMaintenance.NoReparse(marker);if(Directory.Exists(runtime)&&File.Exists(marker)&&File.ReadAllText(marker)==record.RuntimeMarker){var files=new List<string>();var dirs=new List<string>();var pending=new Queue<string>();pending.Enqueue(runtime);while(pending.Count>0){string dir=pending.Dequeue();LauncherMaintenance.NoReparse(dir);dirs.Add(dir);foreach(string file in Directory.GetFiles(dir)){LauncherMaintenance.NoReparse(file);files.Add(file);}foreach(string sub in Directory.GetDirectories(dir)){LauncherMaintenance.NoReparse(sub);pending.Enqueue(sub);}}try{foreach(string file in files)File.Delete(file);foreach(string dir in dirs.OrderByDescending(d=>d.Length))if(!Directory.EnumerateFileSystemEntries(dir).Any())Directory.Delete(dir);}catch{kept.Add("运行缓存（占用，请关闭启动器后重试卸载）");}}
   if(kept.Count==0)File.Delete(Target(root,Manifest));return "卸载完成。未删除游戏、存档、工坊文件或个人设置。"+(kept.Count==0?"":"\n保留："+string.Join("、",kept));
  }
  public static void DeleteSelfAfterExit(string root,string exe){root=ValidateRoot(root);exe=Path.GetFullPath(exe);if(exe!=Target(root,"卸载橙子启动器.exe"))return;string quoted=exe.Replace("'","''"),directory=root.Replace("'","''"),hash=DlssInstaller.HashFile(exe);int pid=Process.GetCurrentProcess().Id;string command="$p=Get-Process -Id "+pid+" -ErrorAction SilentlyContinue; if($p){$p.WaitForExit()}; $t='"+quoted+"'; if((Test-Path -LiteralPath $t) -and (Get-FileHash -LiteralPath $t).Hash -eq '"+hash+"'){Remove-Item -LiteralPath $t -Force}; $d='"+directory+"'; if((Test-Path -LiteralPath $d) -and @(Get-ChildItem -LiteralPath $d -Force).Count -eq 0){Remove-Item -LiteralPath $d}";string encoded=Convert.ToBase64String(Encoding.Unicode.GetBytes(command));Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand "+encoded){UseShellExecute=false,CreateNoWindow=true}).Dispose();}
  public static byte[] Resource(string name){using(var input=typeof(Program).Assembly.GetManifestResourceStream(name)){if(input==null)throw new Exception("安装资源缺失："+name);using(var output=new MemoryStream()){input.CopyTo(output);return output.ToArray();}}}
 }
}
